import * as z from "zod";

/**
 * Zod schemas for the three catalogue files in `src/data/`.
 * `products.json` is generated by `npm run products:sync`;
 * `categories.json` and `overrides.json` are edited by the shop owner.
 * Types are inferred from the schemas so there is one source of truth.
 */

const KEBAB = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const IMAGE_PATH = /^\/products\/[a-z0-9-]+\/[a-z0-9-]+\/\d{2}\.(?:jpg|jpeg|png|webp)$/;

export const DEPARTMENTS = ["books", "stationery", "paper", "office"] as const;
export const DepartmentSchema = z.enum(DEPARTMENTS);

/** Price units shown next to a price; labels live in the en/ur dictionaries. */
export const UNITS = ["box", "pack", "jar", "piece", "ream"] as const;
export const UnitSchema = z.enum(UNITS);

export const HOME_SECTIONS = ["stationery", "new"] as const;
export const HomeSectionSchema = z.enum(HOME_SECTIONS);

const slug = z.string().regex(KEBAB, "must be lowercase kebab-case");

export const SpecSchema = z.strictObject({
  label: z.string().min(1),
  value: z.string().min(1),
});

export const ProductSchema = z.strictObject({
  id: slug,
  title: z.string().min(1),
  name: z.string().min(1),
  brand: z.string().min(1).nullable(),
  category: slug,
  price: z.number().int().positive(),
  priceNote: z.string().min(1).nullable(),
  description: z.array(z.string().min(1)),
  specs: z.array(SpecSchema),
  features: z.array(z.string().min(1)),
  images: z.array(z.string().regex(IMAGE_PATH, "must be /products/<category>/<id>/NN.<ext>")).min(1),
  source: z.string().startsWith("Products/"),
});

export const ProductsSchema = z.array(ProductSchema).superRefine((list, ctx) => {
  const seen = new Set<string>();
  list.forEach((p, i) => {
    if (seen.has(p.id)) ctx.addIssue({ code: "custom", path: [i, "id"], message: `duplicate product id "${p.id}"` });
    seen.add(p.id);
  });
});

export const CategorySchema = z.strictObject({
  slug,
  name: z.strictObject({ en: z.string().min(1), ur: z.string().min(1).nullable() }),
  /** Empty until the owner assigns one; such products appear only under All products. */
  departments: z.array(DepartmentSchema),
  order: z.number().int(),
  /** Folder names in Products/ that map to this category, e.g. "Sharpners". */
  aliases: z.array(z.string().min(1)),
});

export const CategoriesSchema = z.array(CategorySchema).superRefine((list, ctx) => {
  const slugs = new Set<string>();
  const aliases = new Map<string, string>();
  list.forEach((c, i) => {
    if (slugs.has(c.slug)) ctx.addIssue({ code: "custom", path: [i, "slug"], message: `duplicate category slug "${c.slug}"` });
    slugs.add(c.slug);
    c.aliases.forEach((a) => {
      const key = a.toLowerCase();
      const owner = aliases.get(key);
      if (owner && owner !== c.slug) {
        ctx.addIssue({ code: "custom", path: [i, "aliases"], message: `alias "${a}" is also used by "${owner}"` });
      }
      aliases.set(key, c.slug);
    });
  });
});

export const OverrideSchema = z.strictObject({
  active: z.boolean().optional(),
  sort: z.number().int().optional(),
  homeSection: HomeSectionSchema.nullable().optional(),
  bestSeller: z.boolean().optional(),
  offerPrice: z.number().int().positive().nullable().optional(),
  /** Owner-confirmed brand when the .txt has no `* Brand:` line. */
  brand: z.string().min(1).optional(),
  unit: UnitSchema.nullable().optional(),
  /** Source photo file names in display order; the first is the cover. Applied by products:sync. */
  imageOrder: z.array(z.string().min(1)).optional(),
});

export const OverridesSchema = z.record(slug, OverrideSchema);

export type Department = z.infer<typeof DepartmentSchema>;
export type Unit = z.infer<typeof UnitSchema>;
export type HomeSection = z.infer<typeof HomeSectionSchema>;
export type Spec = z.infer<typeof SpecSchema>;
export type Product = z.infer<typeof ProductSchema>;
export type Category = z.infer<typeof CategorySchema>;
export type Override = z.infer<typeof OverrideSchema>;
export type Overrides = z.infer<typeof OverridesSchema>;

/** Formats zod issues as "file: path — message" lines for build-time errors. */
export function formatIssues(file: string, error: z.ZodError): string {
  return error.issues
    .map((issue) => `${file}: ${issue.path.length ? issue.path.join(".") : "(root)"} — ${issue.message}`)
    .join("\n");
}
